package hu.boltseged.admin;
import hu.boltseged.shipment.ShipmentRepository; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/admin/billing") public class BillingSummaryController {final ShipmentRepository repo;BillingSummaryController(ShipmentRepository r){repo=r;}@GetMapping("/summary") List<Summary> summary(@RequestParam(required=false)UUID accountId,@RequestParam(required=false)String billingStatus,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return repo.summaryByCurrency(accountId,billingStatus,from,to).stream().map(x->{BigDecimal cost=(BigDecimal)x[1],price=(BigDecimal)x[2];return new Summary(((Number)x[0]).longValue(),cost,price,price.subtract(cost),(String)x[3]);}).toList();}record Summary(long shipmentCount,BigDecimal totalDhlEstimatedCost,BigDecimal totalCustomerPrice,BigDecimal totalMargin,String currency){}}
